# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AYNI DOĞRULTULU VEKTÖRLER VE UÇ UCA EKLEME YÖNTEMİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">AYNI DOĞRULTULU VEKTÖRLER</text>\n  <text x="40" y="92" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Aynı Yönlü Vektörler (α = 0°):</text>\n  <line x1="45" y1="108" x2="135" y2="108" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="135,103 145,108 135,113" fill="#2563eb"/>\n  <text x="90" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">K = 4 br</text>\n  <line x1="150" y1="108" x2="215" y2="108" stroke="#16a34a" stroke-width="3"/>\n  <polygon points="215,103 225,108 215,113" fill="#16a34a"/>\n  <text x="185" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">L = 3 br</text>\n  <text x="235" y="112" font-size="11" font-weight="bold" fill="#0f172a">→ R_max = K + L = 7 br</text>\n  <text x="40" y="146" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Zıt Yönlü Vektörler (α = 180°):</text>\n  <line x1="45" y1="164" x2="145" y2="164" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="145,159 155,164 145,169" fill="#2563eb"/>\n  <line x1="220" y1="164" x2="170" y2="164" stroke="#dc2626" stroke-width="3"/>\n  <polygon points="170,159 160,164 170,169" fill="#dc2626"/>\n  <text x="45" y="192" font-size="11" font-weight="bold" fill="#991b1b">→ R_min = |K - L| = 1 br (Büyük olanın yönünde)</text>\n  <text x="45" y="218" font-size="11" fill="#1e40af">Bileşke Aralığı: |K - L| ≤ R ≤ K + L</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">UÇ UCA EKLEME YÖNTEMİ</text>\n  <line x1="395" y1="185" x2="495" y2="185" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="495,180 505,185 495,190" fill="#2563eb"/>\n  <text x="445" y="202" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">A Vektörü</text>\n  <line x1="505" y1="185" x2="575" y2="95" stroke="#16a34a" stroke-width="3"/>\n  <polygon points="570,93 580,88 578,99" fill="#16a34a"/>\n  <text x="558" y="145" font-size="11.5" font-weight="bold" fill="#15803d">B Vektörü</text>\n  <line x1="395" y1="185" x2="572" y2="93" stroke="#dc2626" stroke-width="3" stroke-dasharray="5,3"/>\n  <polygon points="568,90 579,89 573,99" fill="#dc2626"/>\n  <text x="468" y="128" font-size="12" font-weight="bold" fill="#dc2626">R = A + B</text>\n  <text x="515" y="226" text-anchor="middle" font-size="11" fill="#78350f">İlk vektörün başlangıcından son vektörün bitiş ucuna çizilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PARALELKENAR YÖNTEMİ VE ÖZEL AÇILAR (60°, 90°, 120°)</text>\n  <rect x="25" y="42" width="305" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="177" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">PARALELKENAR YÖNTEMİ</text>\n  <line x1="65" y1="185" x2="185" y2="185" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="185,180 195,185 185,190" fill="#2563eb"/>\n  <text x="130" y="203" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">F₁</text>\n  <line x1="65" y1="185" x2="115" y2="95" stroke="#9333ea" stroke-width="3"/>\n  <polygon points="110,95 119,88 119,99" fill="#9333ea"/>\n  <text x="75" y="135" font-size="11.5" font-weight="bold" fill="#6b21a8">F₂</text>\n  <line x1="119" y1="88" x2="249" y2="88" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="195" y1="185" x2="249" y2="88" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="65" y1="185" x2="242" y2="92" stroke="#dc2626" stroke-width="3"/>\n  <polygon points="239,88 249,88 244,97" fill="#dc2626"/>\n  <text x="175" y="125" font-size="12" font-weight="bold" fill="#dc2626">R = F₁ + F₂</text>\n  <text x="177" y="226" text-anchor="middle" font-size="11" fill="#14532d">Başlangıç noktaları birleştirilir, köşegen bileşkeyi verir.</text>\n  <rect x="345" y="42" width="330" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="510" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">EŞİT BÜYÜKLÜKTEKİ İKİ VEKTÖR (F₁ = F₂ = F)</text>\n  <text x="362" y="94" font-size="12" font-weight="bold" fill="#581c87">• Açı α = 0° (Aynı Yönlü)  →  R = 2F</text>\n  <text x="362" y="120" font-size="12" font-weight="bold" fill="#581c87">• Açı α = 60° ise  →  R = F·kök(3)</text>\n  <text x="362" y="146" font-size="12" font-weight="bold" fill="#581c87">• Açı α = 90° (Dik) ise  →  R = F·kök(2)  (Pisagor)</text>\n  <text x="362" y="172" font-size="12" font-weight="bold" fill="#581c87">• Açı α = 120° ise  →  R = F</text>\n  <text x="362" y="198" font-size="12" font-weight="bold" fill="#581c87">• Açı α = 180° (Zıt Yönlü)  →  R = 0</text>\n  <rect x="362" y="208" width="296" height="26" rx="5" fill="#f3e8ff"/>\n  <text x="510" y="225" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Açı küçüldükçe bileşke (R) büyür; bileşke büyük kuvvete yakındır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">VEKTÖRÜN DİK BİLEŞENLERİNE AYRILMASI (KARTEZYEN SİSTEM)</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>\n  <line x1="70" y1="205" x2="310" y2="205" stroke="#475569" stroke-width="2"/>\n  <text x="320" y="209" font-size="12" font-weight="bold" fill="#334155">+x</text>\n  <line x1="70" y1="205" x2="70" y2="60" stroke="#475569" stroke-width="2"/>\n  <text x="65" y="53" font-size="12" font-weight="bold" fill="#334155">+y</text>\n  <line x1="70" y1="205" x2="240" y2="95" stroke="#dc2626" stroke-width="3.5"/>\n  <polygon points="236,91 247,90 242,100" fill="#dc2626"/>\n  <text x="165" y="135" font-size="13" font-weight="bold" fill="#dc2626">F</text>\n  <line x1="247" y1="90" x2="247" y2="205" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="247" y1="90" x2="70" y2="90" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="70" y1="205" x2="240" y2="205" stroke="#2563eb" stroke-width="3.5"/>\n  <polygon points="240,200 248,205 240,210" fill="#2563eb"/>\n  <text x="160" y="225" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">F_x = F · cos α</text>\n  <line x1="70" y1="205" x2="70" y2="96" stroke="#16a34a" stroke-width="3.5"/>\n  <polygon points="65,98 70,89 75,98" fill="#16a34a"/>\n  <text x="115" y="82" font-size="12" font-weight="bold" fill="#15803d">F_y = F · sin α</text>\n  <text x="108" y="198" font-size="12" font-weight="bold" fill="#0f172a">α</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">DİK BİLEŞEN BAĞINTILARI</text>\n  <text x="378" y="95" font-size="12" font-weight="bold" fill="#7c2d12">• Yatay Bileşen:  F_x = F · cos α</text>\n  <text x="378" y="120" font-size="12" font-weight="bold" fill="#7c2d12">• Düşey Bileşen:  F_y = F · sin α</text>\n  <text x="378" y="145" font-size="12" font-weight="bold" fill="#c2410c">• Büyüklük (Pisagor):  F² = F_x² + F_y²</text>\n  <rect x="378" y="162" width="280" height="66" rx="6" fill="#ffedd5" stroke="#fb923c"/>\n  <text x="517" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Çoklu Vektörlerde Toplama Adımları:</text>\n  <text x="517" y="200" text-anchor="middle" font-size="11" fill="#7c2d12">1) R_x = ΣF_x  ve  R_y = ΣF_y hesaplanır.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">2) R = kök(R_x² + R_y²) ile bileşke bulunur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
